function place(api, g, x, y, s, o) { api.set(g, {transform: `translate(${x.toFixed(1)} ${y.toFixed(1)}) scale(${s.toFixed(3)})`, opacity: o.toFixed(3), display: o > 0 ? "inline" : "none"}); }
